import type Database from "better-sqlite3";

/** All derived results participate in the same atomic snapshot publication. */
export const ATTRIBUTION_RESULT_TABLES = ["commits", "writers", "alternatives", "turns"] as const;

/** Derived analysis only. Native sessions are never merged, rewritten or removed here. */
export function createAttributionSchema(db: Database.Database): void {
  db.transaction(() => {
    // Pre-release storage reset: old results will be regenerated by collection.
    // Never leave a completed run whose writer summaries have not been produced.
    if (db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name IN ('adit_attribution_lines','adit_attribution_evidence','adit_attribution_candidates') LIMIT 1").get()) {
      db.exec(`
        DROP TABLE IF EXISTS adit_attribution_candidates;
        DROP TABLE IF EXISTS adit_attribution_lines;
        DROP TABLE IF EXISTS adit_attribution_evidence;
        DELETE FROM adit_attribution_commits;
        DELETE FROM adit_attribution_runs;
      `);
    }
    db.exec(`
    CREATE TABLE IF NOT EXISTS adit_attribution_runs (
      id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, algorithm_version INTEGER NOT NULL,
      input_fingerprint TEXT NOT NULL, status TEXT NOT NULL, started_at INTEGER NOT NULL,
      finished_at INTEGER, error TEXT, commit_count INTEGER NOT NULL DEFAULT 0,
      completed_count INTEGER NOT NULL DEFAULT 0, missing_time_count INTEGER NOT NULL DEFAULT 0,
      missing_backup_count INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS adit_attribution_runs_workspace ON adit_attribution_runs(workspace_id,started_at DESC);
    CREATE TABLE IF NOT EXISTS adit_attribution_commits (
      run_id TEXT NOT NULL REFERENCES adit_attribution_runs(id) ON DELETE CASCADE,
      repository TEXT NOT NULL, sha TEXT NOT NULL,
      submit_provider TEXT, submit_session_id TEXT, submit_turn_id TEXT, submit_tool_call_id TEXT,
      match_method TEXT, matched_sha TEXT,
      eligible_lines INTEGER NOT NULL, excluded_lines INTEGER NOT NULL,
      certain_lines INTEGER NOT NULL, likely_lines INTEGER NOT NULL, possible_lines INTEGER NOT NULL,
      moved_lines INTEGER NOT NULL, unknown_lines INTEGER NOT NULL,
      PRIMARY KEY(run_id,repository,sha)
    );
    CREATE TABLE IF NOT EXISTS adit_attribution_writers (
      run_id TEXT NOT NULL REFERENCES adit_attribution_runs(id) ON DELETE CASCADE,
      repository TEXT NOT NULL, sha TEXT NOT NULL,
      provider TEXT NOT NULL, session_id TEXT NOT NULL, file_path TEXT NOT NULL,
      certain_lines INTEGER NOT NULL, likely_lines INTEGER NOT NULL, possible_lines INTEGER NOT NULL,
      PRIMARY KEY(run_id,repository,sha,provider,session_id,file_path)
    );
    CREATE TABLE IF NOT EXISTS adit_attribution_alternatives (
      run_id TEXT NOT NULL REFERENCES adit_attribution_runs(id) ON DELETE CASCADE,
      repository TEXT NOT NULL, sha TEXT NOT NULL,
      writer_provider TEXT NOT NULL, writer_session_id TEXT NOT NULL,
      provider TEXT NOT NULL, session_id TEXT NOT NULL,
      certain_lines INTEGER NOT NULL, likely_lines INTEGER NOT NULL, possible_lines INTEGER NOT NULL,
      PRIMARY KEY(run_id,repository,sha,writer_provider,writer_session_id,provider,session_id)
    );
    CREATE TABLE IF NOT EXISTS adit_attribution_turns (
      run_id TEXT NOT NULL REFERENCES adit_attribution_runs(id) ON DELETE CASCADE,
      repository TEXT NOT NULL, sha TEXT NOT NULL,
      provider TEXT NOT NULL, session_id TEXT NOT NULL,
      turn_id TEXT NOT NULL DEFAULT '',
      PRIMARY KEY(run_id,repository,sha,provider,session_id,turn_id)
    );
  `);
  })();
}
